begin;
create function pg_temp.ok(v boolean,msg text) returns void language plpgsql as $$begin if v is not true then raise exception 'FAIL %',msg;end if;raise notice 'PASS %',msg;end;$$;
insert into auth.users values('32810000-0000-4000-8000-000000000001'),('32810000-0000-4000-8000-000000000002'),('32810000-0000-4000-8000-000000000003');
insert into public.mc_accounts(user_id,subscription_until) select id,now()+interval '1 month' from auth.users;
set local role authenticated;
select set_config('request.jwt.claim.sub','32810000-0000-4000-8000-000000000001',true);
select set_config('fixture.cart',public.mc_create_cart('Ficticio','Emoliente',4,'DNI','00000000','Propietario Ficticio','999999999',null,null,null,null)::text,true);
select public.mc_sync_rents();select public.mc_sync_rents();
select pg_temp.ok((select count(*)=1 from public.mc_movements where kind='RENT'),'Un solo alquiler por carrito y día');
select public.mc_record_movement(current_setting('fixture.cart')::bigint,'PRODUCT','Hielo',2,1.50,3,null);
select public.mc_record_movement(current_setting('fixture.cart')::bigint,'PAYMENT','Abono',null,null,-2,'Efectivo');
select pg_temp.ok((public.mc_my_cart_balances_v328()->0->>'balance_local')::numeric=5,'4 alquiler + 3 hielo - 2 abono = 5');
do $$begin
 begin perform public.mc_record_movement(current_setting('fixture.cart')::bigint,'PAYMENT','Exceso',null,null,-6,'Efectivo');raise exception 'FAIL sobrepago';exception when others then if sqlerrm='FAIL sobrepago' then raise;end if;end;
 begin perform public.mc_record_movement(current_setting('fixture.cart')::bigint,'PRODUCT','Cantidad inválida',-1,2,-2,null);raise exception 'FAIL cantidad';exception when others then if sqlerrm='FAIL cantidad' then raise;end if;end;
 begin perform public.mc_configure_currency('USD','US');raise exception 'FAIL conversión histórica';exception when others then if sqlerrm='FAIL conversión histórica' then raise;end if;end;
end;$$;
select public.mc_change_cart_state(current_setting('fixture.cart')::bigint,'RETIRED');
select pg_temp.ok((public.mc_my_cart_balances_v328()->0->>'balance_local')::numeric=5,'Retiro conserva deuda');
do $$begin begin perform public.mc_record_movement(current_setting('fixture.cart')::bigint,'PRODUCT','No permitido',1,2,2,null);raise exception 'FAIL venta retirado';exception when others then if sqlerrm='FAIL venta retirado' then raise;end if;end;end;$$;
select public.mc_record_movement(current_setting('fixture.cart')::bigint,'PAYMENT','Abono retirado',null,null,-1,'Plin');
select public.mc_change_cart_state(current_setting('fixture.cart')::bigint,'ACTIVE');select public.mc_sync_rents();
select pg_temp.ok((select count(*)=1 from public.mc_movements where kind='RENT'),'Reactivar el mismo día no duplica alquiler');
select set_config('request.jwt.claim.sub','32810000-0000-4000-8000-000000000002',true);
select public.mc_configure_currency('USD','US');
do $$begin begin perform public.mc_record_movement(current_setting('fixture.cart')::bigint,'PAYMENT','Ajeno',null,null,-1,'Efectivo');raise exception 'FAIL cobro ajeno';exception when others then if sqlerrm='FAIL cobro ajeno' then raise;end if;end;end;$$;
select pg_temp.ok((select count(*)=0 from public.mc_carts),'Otro dueño no lee carritos ajenos');
reset role;
update public.mc_accounts set suspended=true where user_id='32810000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','32810000-0000-4000-8000-000000000001',true);
do $$begin begin perform public.mc_sync_rents();raise exception 'FAIL suspendido';exception when others then if sqlerrm='FAIL suspendido' then raise;end if;end;end;$$;
reset role;
select pg_temp.ok((select count(*)=1 from public.mc_movements where kind='PRODUCT'),'Operaciones rechazadas no crean ventas');
select pg_temp.ok(not has_function_privilege('anon','public.mc_record_movement(bigint,text,text,numeric,numeric,numeric,text)','execute'),'Anónimo sin permisos para cobrar');
rollback;
